void audioResetPeaks() {
  NVIC_DisableIRQ(SWPMI1_IRQn);
  gCounts.late = 0;
  gLate.clearCount();
  gCounts.overruns = 0;
  gCounts.maxCycles = 0;
  gSumCycles = 0;
  gSumBlocks = 0;
  for (int s = 0; s < kStatBuckets; ++s) {
    gSlotCycles[s] = 0;
    gSlotWorst[s] = 0;
  }
  NVIC_EnableIRQ(SWPMI1_IRQn);
}
#endif

uint32_t audioBlockCount() { return gCounts.blocks; }

level::InputEnergy audioTakeInputEnergy() {
  NVIC_DisableIRQ(SWPMI1_IRQn);
  level::InputEnergy energy;
  energy.sumSquares = gInputSumSquares;
  energy.samples = gInputSamples;
  gInputSumSquares = 0.0f;
  gInputSamples = 0;
  NVIC_EnableIRQ(SWPMI1_IRQn);
  return energy;
}

level::OutputEnergy audioTakeOutputEnergy() {
  NVIC_DisableIRQ(SWPMI1_IRQn);
  level::OutputEnergy energy;
  energy.sumSquares = gOutputSumSquares;
  energy.samples = gOutputSamples;
  gOutputSumSquares = 0.0f;
  gOutputSamples = 0;
  NVIC_EnableIRQ(SWPMI1_IRQn);
  return energy;
}

float audioTakeGatePeak() {
  NVIC_DisableIRQ(SWPMI1_IRQn);
  const float peak = gGatePeak;
  gGatePeak = 0.0f;
  NVIC_EnableIRQ(SWPMI1_IRQn);
  return peak;
}

AudioStats audioStats() {
  uint64_t sumCycles;
  uint32_t n;
  std::array<uint64_t, kStatBuckets> slotCycles;
  AudioStats s;

  // Copy under the mask, divide after: the 64-bit divides are too slow to hold the IRQ off.
  NVIC_DisableIRQ(SWPMI1_IRQn);
  s.blocks = gCounts.blocks;
  s.late = gCounts.late;
  s.dryBlocks = gLate.dryBlocks();
  s.overruns = gCounts.overruns;
  s.maxCycles = gCounts.maxCycles;
  s.budgetCycles = gCounts.budgetCycles;
  sumCycles = gSumCycles;
  n = gSumBlocks;
  for (size_t i = 0; i < slotCycles.size(); ++i) {
    slotCycles[i] = gSlotCycles[i];
    s.slotWorst[i] = gSlotWorst[i];
  }
  NVIC_EnableIRQ(SWPMI1_IRQn);

  s.avgCycles = n ? static_cast<uint32_t>(sumCycles / n) : 0;
  for (size_t i = 0; i < slotCycles.size(); ++i) s.slotAvg[i] = n ? static_cast<uint32_t>(slotCycles[i] / n) : 0;
  return s;
}
